biomarkerBase <- if (requireNamespace("jmvcore", quietly=TRUE)) R6::R6Class(
    "biomarkerBase",
    inherit = jmvcore::Analysis,
    public = list(
        initialize = function(options, data=NULL, datasetId="", analysisId="", revision=0) {
            super$initialize(
                package = "jmsequential",
                name = "biomarker",
                version = c(0,1,0),
                options = options,
                results = biomarkerResults$new(options=options),
                data = data,
                datasetId = datasetId,
                analysisId = analysisId,
                revision = revision,
                pause = NULL,
                completeWhenFilled = FALSE,
                requiresMissings = FALSE,
                weightsSupport = 'auto')
        }))

#' Biomarker-Stratified Phase II
#'
#' Phase II designs stratified by a biomarker, which decide both whether to go 
#' to phase III and in which population (biomarker-positive only, 
#' biomarker-stratified, all-comers). Randomized designs with the decision 
#' algorithm of Freidlin et al. (2012); single-arm stratified two-stage 
#' designs (Parashar et al. 2016, Li & Ivanova 2024, Jones & Holmgren 2007, 
#' parallel Simon designs). Binary response or time to event; fixed stratum 
#' sizes or natural prevalence; exact operating characteristics, and 
#' patient-level analysis.
#' @param data .
#' @param trial .
#' @param endpoint .
#' @param sizes .
#' @param prev .
#' @param alpha1 .
#' @param alpha2 .
#' @param power .
#' @param alloc .
#' @param ratioNeg .
#' @param level .
#' @param hrTarget .
#' @param hrMid .
#' @param hrNoBen .
#' @param hrBen .
#' @param pcPos .
#' @param pcNeg .
#' @param diffTarget .
#' @param diffMid .
#' @param diffNoBen .
#' @param diffBen .
#' @param medPos .
#' @param medNeg .
#' @param accrual .
#' @param followUp .
#' @param dropoutProb .
#' @param dropoutTime .
#' @param interim .
#' @param frac .
#' @param zfut .
#' @param saDesign .
#' @param saType .
#' @param saAlpha .
#' @param saPower .
#' @param p0Neg .
#' @param p0Pos .
#' @param p1Neg .
#' @param p1Pos .
#' @param lmTime .
#' @param m0Neg .
#' @param m0Pos .
#' @param m1Neg .
#' @param m1Pos .
#' @param nMaxNeg .
#' @param nMaxPos .
#' @param udN1Neg .
#' @param udK1Neg .
#' @param udN1Pos .
#' @param udK1Pos .
#' @param udNNeg .
#' @param udKNeg .
#' @param udNPos .
#' @param udKPos .
#' @param udNePos .
#' @param udKePos .
#' @param userScen .
#' @param userPos .
#' @param userNeg .
#' @param biomarker .
#' @param bmLevel .
#' @param arm .
#' @param armLevel .
#' @param response .
#' @param respLevel .
#' @param time .
#' @param event .
#' @param eventLevel .
#' @param ciLevel .
#' @param ocTable .
#' @param regionPlot .
#' @param ocMap .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$searchCache} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$summary} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$sizes} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$rules} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$oc} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$observed} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$decision} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$regionPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$ocMap} \tab \tab \tab \tab \tab an image \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$searchCache$asDF}
#'
#' \code{as.data.frame(results$searchCache)}
#'
#' @export
biomarker <- function(
    data,
    trial = "randomized",
    endpoint = "surv",
    sizes = "fixed",
    prev = 0.33,
    alpha1 = 0.1,
    alpha2 = 0.05,
    power = 0.9,
    alloc = 1,
    ratioNeg = 2,
    level = 0.8,
    hrTarget = 0.5,
    hrMid = 0.667,
    hrNoBen = 0.769,
    hrBen = 0.667,
    pcPos = 0.2,
    pcNeg = 0.2,
    diffTarget = 0.3,
    diffMid = 0.2,
    diffNoBen = 0.1,
    diffBen = 0.2,
    medPos = 4,
    medNeg = 4,
    accrual = 21,
    followUp = 6,
    dropoutProb = 0,
    dropoutTime = 12,
    interim = FALSE,
    frac = 0.5,
    zfut = 0,
    saDesign = "parashar",
    saType = "optimal",
    saAlpha = 0.05,
    saPower = 0.8,
    p0Neg = 0.2,
    p0Pos = 0.2,
    p1Neg = 0.4,
    p1Pos = 0.5,
    lmTime = 6,
    m0Neg = 3,
    m0Pos = 3,
    m1Neg = 6,
    m1Pos = 8,
    nMaxNeg = 0,
    nMaxPos = 0,
    udN1Neg = 16,
    udK1Neg = 5,
    udN1Pos = 8,
    udK1Pos = 3,
    udNNeg = 49,
    udKNeg = 15,
    udNPos = 17,
    udKPos = 7,
    udNePos = 32,
    udKePos = 12,
    userScen = FALSE,
    userPos = 0.6,
    userNeg = 0.9,
    biomarker = NULL,
    bmLevel,
    arm = NULL,
    armLevel,
    response = NULL,
    respLevel,
    time = NULL,
    event = NULL,
    eventLevel,
    ciLevel = 0.95,
    ocTable = TRUE,
    regionPlot = TRUE,
    ocMap = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("biomarker requires jmvcore to be installed (restart may be required)")

    if ( ! missing(biomarker)) biomarker <- jmvcore::resolveQuo(jmvcore::enquo(biomarker))
    if ( ! missing(arm)) arm <- jmvcore::resolveQuo(jmvcore::enquo(arm))
    if ( ! missing(response)) response <- jmvcore::resolveQuo(jmvcore::enquo(response))
    if ( ! missing(time)) time <- jmvcore::resolveQuo(jmvcore::enquo(time))
    if ( ! missing(event)) event <- jmvcore::resolveQuo(jmvcore::enquo(event))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(biomarker), biomarker, NULL),
            `if`( ! missing(arm), arm, NULL),
            `if`( ! missing(response), response, NULL),
            `if`( ! missing(time), time, NULL),
            `if`( ! missing(event), event, NULL))

    for (v in biomarker) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])
    for (v in arm) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])
    for (v in response) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])
    for (v in event) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])

    options <- biomarkerOptions$new(
        trial = trial,
        endpoint = endpoint,
        sizes = sizes,
        prev = prev,
        alpha1 = alpha1,
        alpha2 = alpha2,
        power = power,
        alloc = alloc,
        ratioNeg = ratioNeg,
        level = level,
        hrTarget = hrTarget,
        hrMid = hrMid,
        hrNoBen = hrNoBen,
        hrBen = hrBen,
        pcPos = pcPos,
        pcNeg = pcNeg,
        diffTarget = diffTarget,
        diffMid = diffMid,
        diffNoBen = diffNoBen,
        diffBen = diffBen,
        medPos = medPos,
        medNeg = medNeg,
        accrual = accrual,
        followUp = followUp,
        dropoutProb = dropoutProb,
        dropoutTime = dropoutTime,
        interim = interim,
        frac = frac,
        zfut = zfut,
        saDesign = saDesign,
        saType = saType,
        saAlpha = saAlpha,
        saPower = saPower,
        p0Neg = p0Neg,
        p0Pos = p0Pos,
        p1Neg = p1Neg,
        p1Pos = p1Pos,
        lmTime = lmTime,
        m0Neg = m0Neg,
        m0Pos = m0Pos,
        m1Neg = m1Neg,
        m1Pos = m1Pos,
        nMaxNeg = nMaxNeg,
        nMaxPos = nMaxPos,
        udN1Neg = udN1Neg,
        udK1Neg = udK1Neg,
        udN1Pos = udN1Pos,
        udK1Pos = udK1Pos,
        udNNeg = udNNeg,
        udKNeg = udKNeg,
        udNPos = udNPos,
        udKPos = udKPos,
        udNePos = udNePos,
        udKePos = udKePos,
        userScen = userScen,
        userPos = userPos,
        userNeg = userNeg,
        biomarker = biomarker,
        bmLevel = bmLevel,
        arm = arm,
        armLevel = armLevel,
        response = response,
        respLevel = respLevel,
        time = time,
        event = event,
        eventLevel = eventLevel,
        ciLevel = ciLevel,
        ocTable = ocTable,
        regionPlot = regionPlot,
        ocMap = ocMap)

    analysis <- biomarkerClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

